INSERT INTO `anime_episodes` VALUES (1,1,'Что такое зло? Всё, что проистекает из слабости.',1,1,1,-1,NULL,1),(2,2,'Нужно немало усилий и мастерства, чтобы скрыть свой талант и умение.',1,1,1,66,NULL,1),(3,3,'Человек — животное, которое умеет заключать сделки. Ни одно другое животное на это не способно: ни одна собака не обменяет кость с другой.',1,1,1,41,NULL,1),(4,4,'Не стоит огорчаться, что другие скрывают от нас правду, когда мы скрываем её от самих себя.',1,1,1,170,NULL,1),(5,5,'Ад — это другие люди.',1,1,1,69,NULL,1),(6,6,'Есть два вида лжи: одна касается свершившегося факта, другая — будущего долга.',1,1,1,70,NULL,1),(7,7,'Нет ничего опаснее невежественного друга; мудрому врагу стоит отдать предпочтение.',1,1,1,81,NULL,1),(8,8,'Оставь надежду, всяк сюда входящий.',1,1,1,197,NULL,1),(9,9,'Человек обречён быть свободным.',1,1,1,-1,NULL,1),(10,10,'В каждом человеке живёт самый опасный предатель.',1,1,1,53,NULL,1),(11,11,'То, что люди обычно называют судьбой, чаще всего — их собственная глупость.',1,1,1,81,NULL,1),(12,12,'Гений живёт всего на один этаж выше безумия.',1,1,1,-1,NULL,1),(13,1,'Помни: в трудные времена нужно сохранять ясную голову.',1,1,1,67,NULL,2),(14,2,'Есть два главных человеческих порока, из которых проистекают все остальные: нетерпение и лень.',1,1,1,95,NULL,2),(15,3,'Величайшие души способны и на величайшие пороки, и на величайшие добродетели',1,1,1,84,NULL,2),(16,4,'Материал нужно создавать.',1,1,1,133,NULL,2),(17,5,'Каждая неудача — шаг к успеху.',1,1,1,88,NULL,2),(18,6,'Испытания — первый путь к истине.',1,1,1,63,NULL,2),(19,7,'Сомневаться во всём или верить всему — два одинаково удобных решения; оба избавляют от необходимости размышлять.',1,1,1,126,NULL,2),(20,8,'Рана — в её сердце.',1,1,1,68,NULL,2),(21,9,'Если ты совершил ошибку и не исправил её, это и называется ошибкой.',1,1,1,69,NULL,2),(22,10,'Люди, часто обманутые иллюзорным благом, стремятся к собственной гибели.',1,1,1,146,NULL,2),(23,11,'Человек, который не умеет властвовать над собой, всегда остаётся рабом.',1,1,1,78,NULL,2),(24,12,'Сила без мудрости рушится под собственным весом.',1,1,1,37,NULL,2),(25,13,'Самый страшный враг, которого ты можешь встретить, — всегда ты сам.',1,1,1,188,NULL,2),(26,1,'Самый мощный принцип роста заключается в человеческом выборе.',1,1,1,-1,NULL,3),(27,2,'Человек человеку волк.',1,1,1,169,NULL,3),(28,3,'Мы никогда не забываем то, что стремимся забыть.',1,1,1,98,NULL,3),(29,4,'У тебя есть право на труд, но не на плоды труда.',1,1,1,72,NULL,3),(30,5,'Удача благоволит смелым.',1,1,1,-1,NULL,3),(31,6,'Лучше самому принять обиду, чем причинить её.',1,1,1,106,NULL,3),(32,7,'Люди готовы на что угодно, каким бы абсурдным это ни было, лишь бы не сталкиваться лицом к лицу с собственной душой.',1,1,1,97,NULL,3),(33,8,'Те, кто не помнит прошлого, обречены повторять его.',1,1,1,-1,NULL,3),(34,9,'Крайняя справедливость — крайняя несправедливость.',1,1,1,93,NULL,3),(35,10,'Главную причину нелепых выводов я вижу в отсутствии метода.',1,1,1,-1,NULL,3),(36,11,'В любви есть только одно правило: приносить счастье тем, кого любишь.',1,1,1,-1,NULL,3),(37,12,'Меняй свои желания, а не порядок мира.',1,1,1,62,NULL,3),(38,13,'Любовь — лучший учитель.',1,1,1,116,NULL,3),(39,1,'Враг из Белой Комнаты',1,1,1,-1,NULL,4),(40,2,'Контракт и награда',1,1,1,81,NULL,4),(41,3,'Решимость лидера',1,1,1,125,NULL,4),(42,4,'На кого направлено лезвие',1,1,1,105,NULL,4),(43,5,'Юноша за 20 миллионов',1,1,1,80,NULL,4),(44,6,'Хаотичное противостояние',1,1,1,49,NULL,4),(45,7,'Заговор',1,1,1,110,NULL,4),(46,8,'На что взирают драконы',1,1,1,29,NULL,4),(47,9,'Зловещее начало',1,1,1,62,NULL,4),(48,10,'Невысказанная любовь',1,1,1,68,NULL,4);
