INSERT INTO `anime_seasons` VALUES (1,'Вышел','Лето 2017','12 июля','Lerche',12,'29 сентября 2022','/images/anime/anime-banner-season-1.webp',1,'В недалёком будущем японское правительство основало Токийскую столичную старшую школу продвинутого воспитания, предназначенную для обучения и взращивания поколения людей, которое в будущем будет поддерживать страну. Ученикам там разрешено носить любые причёски и приносить с собой любые личные вещи по своему желанию.\r\n<br><br>\r\nГлавный герой истории — Киётака Аянокоджи, тихий и неприметный юноша, которому тяжело заводить друзей и который предпочитает держаться в стороне. Он учится в классе D — именно туда школа определяет учеников, которых считает наименее способными, чтобы выставить их на посмешище. После знакомства с Хорикитой Сузуне и Кушидой Кикё, двумя другими ученицами его класса, положение Киётаки начинает меняться.\r\n','https://www.youtube.com/watch?v=RTvdxGyWV6c','С 1 по 3',NULL),(2,'Вышел','Лето 2022','4 июля','Lerche',13,'28 сентября 2022','/images/anime/anime-banner-season-2.webp',2,'«Я одержу победу!»\r\n<br><br>\r\nТокийская столичная высшая школа развития и воспитания — это школа, похожая на рай: она может похвастаться 100-процентным уровнем поступления в университеты и трудоустройства, а также ежемесячно начисляет ученикам личные очки, эквивалентные 100 000 иен. Однако на деле это место, где превыше всего ставится меритократия: благоприятное отношение получают только те, кто демонстрирует выдающиеся результаты.\r\n<br><br>\r\nПопав в класс D, полный проблемных учеников, Киётака Аянокоджи начинает сотрудничать с Хорикитой Сузуне, которая стремится подняться выше и добиться перевода в класс A. После завершения экзамена на выживание на необитаемом острове они получают короткую передышку на роскошном круизном лайнере, однако вскоре начинается новый экзамен, перемешивающий классы.\r\n<br><br>\r\nБудете ли вы работать на благо своего класса, своей группы или самого себя? Пока ученики из других классов совершают тревожные и подозрительные шаги, класс D, которому не хватает сплочённости, оказывается в затруднительном положении.\r\n<br><br>\r\nСмогут ли ученики, колеблясь между доверием и подозрением, разглядеть истину?\r\n<br><br>\r\nНовый школьный апокалипсис вот-вот начнётся.\r\n','https://www.youtube.com/watch?v=a84AQbBnZGM','С 4 по 7.5',NULL),(3,'Вышел','Зима 2024','3 января','Lerche',13,'29 марта 2024','/images/anime/anime-banner-season-3.webp',3,'Токийская столичная старшая школа продвинутого воспитания — словно школа мечты: практически 100% дальнейшее поступление в вузы и трудоустройство после выпуска, а каждый месяц выплачиваются баллы, эквивалентные 100.000 йен наличными. Однако на деле это место, где привилегии получают лишь немногие ученики с выдающимися результатами.<br><br>\r\nС началом третьего триместра Аянокоджи и его друзья, поднявшиеся из класса D в класс C, отправляются в школьную поездку. Там пройдёт специальный экзамен под названием «Смешанный лагерь» — совместное мероприятие для всех параллелей. Как следует из названия, это испытание, в котором группы формируются с разделением по полу, а внутри каждой группы смешиваются ученики из разных классов.<br><br>\r\nЭкзамен оценивается по итогам работы группы, и ученикам из других классов, которые до сих пор были разобщены и соперничали, придётся сотрудничать, чтобы набрать высокий балл. Кроме того, действует правило: из группы, не достигшей проходной границы, будет исключён участник, показавший худший результат.<br><br>\r\nБурный третий триместр, который поднимет шум и вызовет переполох, вот-вот начнётся!','https://www.youtube.com/watch?v=6Gx4pQ14HLk','С 8 по 11.5',NULL),(4,'Онгоинг','Весна 2026','1 апреля','Lerche',16,'23 апреля 2026','/images/anime/anime-banner-season-4.webp',4,'Токийская столичная высшая школа развития и воспитания — это учебное заведение, демонстрирующее 100-процентный показатель поступления в вузы и трудоустройства, при этом ученикам ежемесячно начисляются баллы, эквивалентные 100 000 иен. Однако на практике школа функционирует как система строгой меритократии, где привилегии получает лишь ограниченный круг учеников с высокими результатами.\r\n<br><br>\r\nВ третьем семестре первого года Аянокоджи и его одноклассники поднялись до класса C, но после минимального поражения от класса A в заключительном специальном экзамене были понижены обратно в класс D. В результате их второй учебный год начинается снова с класса D.\r\n<br><br>\r\nВо время весенних каникул Аянокоджи начинает отношения с Каруизавой, тогда как Хорикита решает оставить позади прежнюю версию себя, долгое время ориентировавшуюся на своего выдающегося старшего брата Манабу. На фоне этих постепенных изменений в отношениях они вступают во второй год обучения.\r\n<br><br>\r\nПервый специальный экзамен для второкурсников представляет собой письменный тест, который проходит в парах с новыми первокурсниками. Однако среди новичков находится агент Белой комнаты, направленный Цукисиро.\r\n<br><br>\r\nК чему приведут эти новые межкурсовые связи — к конфликту или стабильности — пока неясно.\r\n<br><br>\r\nНачинается второй год их школьной жизни.','https://www.youtube.com/watch?v=QtIvKG8q5iM','С 1 по 4.5','(12-15.5)');
/*!40000 ALTER TABLE `anime_seasons` ENABLE KEYS */;
